(()=>{
 const previous=EmberViewport.prototype.render;
 EmberViewport.prototype.render=function(particles,settings,grid,light){
  const T=Ember3D;
  if(!this.ribbonMesh){
   const maximum=this.max*6;this.ribbonPositions=new Float32Array(maximum*3);this.ribbonColors=new Float32Array(maximum*4);this.ribbonStyles=new Float32Array(maximum*3);this.ribbonUVs=new Float32Array(maximum*2);
   const geometry=new T.BufferGeometry();for(const [name,array,size]of [['position',this.ribbonPositions,3],['ribbonColor',this.ribbonColors,4],['stripStyle',this.ribbonStyles,3],['stripUV',this.ribbonUVs,2]])geometry.setAttribute(name,new T.BufferAttribute(array,size).setUsage(T.DynamicDrawUsage));
   const material=new T.ShaderMaterial({transparent:true,depthWrite:false,side:T.DoubleSide,vertexShader:`attribute vec4 ribbonColor;attribute vec3 stripStyle;attribute vec2 stripUV;varying vec4 shade;varying vec3 style;varying vec2 uvStrip;void main(){shade=ribbonColor;style=stripStyle;uvStrip=stripUV;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,fragmentShader:`varying vec4 shade;varying vec3 style;varying vec2 uvStrip;void main(){vec3 color=shade.rgb;if(style.x>.5){float crossWidth=abs(uvStrip.x*2.0-1.0);float band=.35+.65*floor(min(1.0-crossWidth,.9999)*style.y)/(style.y-1.0);float ink=style.z>0.0?step(1.0-style.z,crossWidth):0.0;color=mix(color*band,vec3(.008,.01,.018),ink);}gl_FragColor=vec4(color,shade.a);\n#include <tonemapping_fragment>\n#include <colorspace_fragment>\n}`});
   this.ribbonMesh=new T.Mesh(geometry,material);this.ribbonMesh.frustumCulled=false;this.scene.add(this.ribbonMesh);
  }
  let vertex=0;const groups=new Map(),color=new T.Color(),side=new T.Vector3(),tangent=new T.Vector3(),view=new T.Vector3();
  const style=s=>[s.anime?1:0,s.animeSteps??3,(s.animeOutline??8)/100];
  const edge=(p,s,width,alpha=1)=>{side.normalize().multiplyScalar(width*.5);color.set(EmberAnimation.particleColor(s,p.age/p.life));const brightness=s.glow?3:1;return {a:[p.x-side.x,p.y-side.y,p.z-side.z],b:[p.x+side.x,p.y+side.y,p.z+side.z],color:[color.r*brightness,color.g*brightness,color.b*brightness,EmberLifetime.opacity(s,p.age/p.life)*(s.opacity??1)*alpha],style:style(s)};};
  const segment=(a,b)=>{if(vertex+6>this.max*6)return;for(const [e,point,u,v]of [[a,a.a,0,0],[a,a.b,1,0],[b,b.a,0,1],[a,a.b,1,0],[b,b.b,1,1],[b,b.a,0,1]]){this.ribbonPositions.set(point,vertex*3);this.ribbonColors.set(e.color,vertex*4);this.ribbonStyles.set(e.style,vertex*3);this.ribbonUVs.set([u,v],vertex*2);vertex++;}};
  for(const p of particles){const s=p.settings||settings;if(!s.trail)continue;if(s.trailMode==='ribbon'){if(!groups.has(s))groups.set(s,[]);groups.get(s).push(p);}else if(s.anime){const tail=EmberParticles.trailEnd(p,s);tangent.set(p.x-tail.x,p.y-tail.y,p.z-tail.z);if(tangent.lengthSq()<1e-12)continue;view.set(this.camera.position.x-p.x,this.camera.position.y-p.y,this.camera.position.z-p.z);side.crossVectors(tangent,view);if(side.lengthSq()<1e-12)side.set(1,0,0);const width=Math.max(.3,s.size*.35),a=edge(p,s,width,.55);const b=edge({...p,...tail},s,width,.08);segment(a,b);}}
  for(const [s,points]of groups){const edges=points.map((p,i)=>{const before=points[Math.max(0,i-1)],after=points[Math.min(points.length-1,i+1)];tangent.set(after.x-before.x,after.y-before.y,after.z-before.z);view.set(this.camera.position.x-p.x,this.camera.position.y-p.y,this.camera.position.z-p.z);side.crossVectors(tangent,view);if(side.lengthSq()<1e-12)side.set(1,0,0);return edge(p,s,EmberRibbons.width(s,p.age/p.life));});for(let i=1;i<edges.length;i++)segment(edges[i-1],edges[i]);}
  this.ribbonMesh.geometry.setDrawRange(0,vertex);for(const attribute of Object.values(this.ribbonMesh.geometry.attributes))attribute.needsUpdate=true;this.ribbonMesh.visible=vertex>0;previous.call(this,particles,settings,grid,light);
 };
})();
